```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Items are marked seen only once their digest has been published.
        // An unpublished run leaves them unseen so they are considered again.
        let mut recorded: u32 = 0;
        if published.published {
            for id in published.considered.iter() {
                if id.is_empty() {
                    continue;
                }
                // Only newly seen ids count; re-recording an id is a no-op.
                if state_rw::get(id).is_none() {
                    state_rw::put(id, &published.date);
                    recorded = recorded.saturating_add(1);
                }
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

